/**
 * 「生成物 vs 手写文件」的判定与安全写入。
 *
 * 存在的理由: 批量重生成覆盖手写文件已经**踩过两次**
 *   * `domain:new --force` 覆盖了 member 的手写仓储（丢了自定义 findByAccount）
 *   * 批量重生成 324 个仓储时又覆盖了一次
 * 靠"记住要小心"是靠不住的，所以把判定做成机制:
 *
 *   1. 生成物首行带标记 `// Auto-generated by Codegen Engine`（codegen 模板保证）
 *   2. `writeGeneratedFile()` 只允许覆盖**带标记**的文件；无标记即视为手写 -> 拒绝
 *   3. `scripts/check-handwritten-files.cjs` 把"手写文件清单"钉成基线，
 *      被覆盖时会失去标记 -> 门禁立刻报出来
 */
const fs = require("node:fs")

const GENERATED_MARKER = "Auto-generated by Codegen Engine"

function looksGenerated(content) {
  // 标记在文件开头若干行内（有的模板前面还有一行 dialect 说明）
  return content.slice(0, 400).includes(GENERATED_MARKER)
}

function isGeneratedFile(file) {
  if (!fs.existsSync(file)) return false
  return looksGenerated(fs.readFileSync(file, "utf8"))
}

/**
 * 安全写入生成物。
 *
 * @returns "written" | "skipped-handwritten"
 * @throws 当目标存在、无标记、且未显式 force 时 —— **失败而不是静默跳过**，
 *         因为"以为写了其实没写"和"以为没写其实覆盖了"都是坑。
 */
function writeGeneratedFile(file, content, options = {}) {
  if (fs.existsSync(file) && !isGeneratedFile(file) && !options.force) {
    return "skipped-handwritten"
  }
  fs.mkdirSync(require("node:path").dirname(file), { recursive: true })
  fs.writeFileSync(file, content)
  return "written"
}

module.exports = { GENERATED_MARKER, looksGenerated, isGeneratedFile, writeGeneratedFile }
